namespace Kit.CodeShape.Tests;

public sealed class ProjectCheckTests : IDisposable
{
    private const string DeepClass =
        "class Deep { void Run(int a) { if (a > 0) { if (a > 1) { if (a > 2) { if (a > 3) { if (a > 4) { a++; } } } } } } }";

    private readonly DirectoryInfo _folder = Directory.CreateTempSubdirectory("codeshape-");

    public void Dispose() => _folder.Delete(recursive: true);

    // The compiler's own test for generated code, which its analyzers skip too: the file's name, or an
    // <auto-generated> comment at its top.
    [Theory]
    [InlineData("Deep.g.cs", "")]
    [InlineData("Deep.g.i.cs", "")]
    [InlineData("Deep.generated.cs", "")]
    [InlineData("Deep.Designer.cs", "")]
    [InlineData("TemporaryGeneratedFile_Deep.cs", "")]
    [InlineData("Deep.cs", "// <auto-generated/>\n")]
    [InlineData("Deep.cs", "// <auto-generated>\n// Made by a tool.\n// </auto-generated>\n")]
    public void GeneratedFilesAreSkipped(string name, string header)
    {
        string path = Write(name, header + DeepClass);

        ProjectCheck.Check(new ProjectFiles("App.csproj", [], [path])).Should().BeEmpty();
    }

    [Fact]
    public void AFileWithAnAutoGeneratedCommentFurtherDownIsStillChecked()
    {
        string path = Write("Deep.cs", "// Written by hand.\n" + DeepClass + "\n// <auto-generated/>\n");

        ProjectCheck.Check(new ProjectFiles("App.csproj", [], [path])).Should().ContainSingle();
    }

    [Theory]
    [InlineData(new string[0], 0)]
    [InlineData(new[] { "KIT_DEEP" }, 1)]
    public void CodeIsReadWithTheProjectsPreprocessorSymbols(string[] defines, int findings)
    {
        string path = Write("Deep.cs", $"#if KIT_DEEP\n{DeepClass}\n#endif\n");

        ProjectCheck.Check(new ProjectFiles("App.csproj", defines, [path])).Should().HaveCount(findings);
    }

    // Every limit reports, and findings come in path, line and column order, whatever order the files came in.
    [Fact]
    public void EveryLimitReportsInPathLineAndColumnOrder()
    {
        string d = Write("D.cs", string.Join('\n', Enumerable.Repeat("// a line", 801)));
        string c = Write("C.cs", "class Long { void Run(int a) { " + string.Concat(Enumerable.Repeat("a++; ", 101)) + "} }");
        string b = Write("B.cs", DeepClass);
        string a = Write("A.cs", string.Join('\n',
            "class Ledger { private int _a; private int _b; void A() => _a++; void B() { if (_b > 0) { if (_b > 1) { if (_b > 2) { if (_b > 3) { if (_b > 4) { _b++; } } } } } } }",
            "",
            DeepClass.Replace("class Deep", "class Deeper", StringComparison.Ordinal)));

        IEnumerable<string> found = ProjectCheck.Check(new ProjectFiles("App.csproj", [], [d, c, b, a]))
            .Select(finding => $"{Path.GetFileName(finding.Path)}:{finding.Line}:{string.Join(' ', finding.Message.Split(' ').Take(2))}");

        found.Should().Equal("A.cs:1:Ledger's methods", "A.cs:1:B nests", "A.cs:3:Run nests", "B.cs:1:Run nests", "C.cs:1:Run has", "D.cs:801:The file");
    }

    private string Write(string name, string text)
    {
        string path = Path.Join(_folder.FullName, name);
        File.WriteAllText(path, text);
        return path;
    }
}
